+export enum Deliverability {
+  High = 'High',
+  Medium = 'Medium',
+  Low = 'Low',
+  Burned = 'Burned',
+  Unknown = 'Unknown',
+}
+
+export const getDeliverability = (score?: number | null): Deliverability => {
+  if (score === undefined || score === null || Number.isNaN(Number(score))) {
+    return Deliverability.Unknown;
+  }
+  if (Number(score) === 100) return Deliverability.High;
+  if (Number(score) >= 98) return Deliverability.Medium;
+  if (Number(score) >= 95) return Deliverability.Low;
+  return Deliverability.Burned;
+};
+
+export class EmailAccount {
+  smartleadInboxId: string;
+  smartleadClientId: string;
+  email: string;
+  domain: string;
+  tags: string[];
+  campaignIds: string[];
+  createdAt?: string;
+  warmupReputation?: number;
+
+  constructor(data: Partial<EmailAccount>) {
+    Object.assign(this, data);
+    this.smartleadInboxId = String(data.smartleadInboxId);
+    this.smartleadClientId = String(data.smartleadClientId);
+    this.email = data.email;
+    this.domain = EmailAccount.domainFromEmail(data.email);
+    this.tags = [...new Set(data.tags ?? [])];
+    this.campaignIds = [...new Set(data.campaignIds ?? [])];
+    this.warmupReputation = EmailAccount.toOptionalNumber(
+      data.warmupReputation,
+    );
+  }
+
+  get numberOfCampaignAssociated(): number {
+    return this.campaignIds.length;
+  }
+
+  get deliverability(): Deliverability {
+    return getDeliverability(this.warmupReputation);
+  }
+
+  get deliverabilityScore(): number | undefined {
+    return this.warmupReputation;
+  }
+
+  private static domainFromEmail(email?: string): string {
+    const separator = email?.lastIndexOf('@') ?? -1;
+    return separator >= 0 ? email.slice(separator + 1).toLowerCase() : '';
+  }
+
+  private static toOptionalNumber(value?: number): number | undefined {
+    if (value === undefined || value === null || Number.isNaN(Number(value))) {
+      return undefined;
+    }
+    return Number(value);
+  }
+}
