+import {
+  Injectable,
+  Logger,
+  NotFoundException,
+  Optional,
+} from '@nestjs/common';
+import { DatastoreService } from '../datastore/datastore.service';
+import { StoreDataDto } from '../datastore/dto/store.dto';
+import { documentType } from '../datastore/entites/documentType';
+import { EmailAccountDto, EmailAccountListDto } from './dto/emailAccount.dto';
+import { EmailAccount } from './entities/emailinfra.entity';
+
+const DEFAULT_CAMPAIGN_DAYS = 10;
+const DEFAULT_EMAILS_PER_INBOX_PER_DAY = 20;
+
+@Injectable()
+export class EmailinfraService {
+  private readonly logger = new Logger(EmailinfraService.name);
+
+  constructor(
+    @Optional() private readonly datastoreService?: DatastoreService,
+  ) {}
+
+  async getBestEmailAccountsForCampaign({
+    smartleadClientId,
+    numberOfDaysInCampaign = DEFAULT_CAMPAIGN_DAYS,
+    totalNumberOfEmailsToSend,
+    emailsPerInboxPerDay = DEFAULT_EMAILS_PER_INBOX_PER_DAY,
+  }: EmailAccountListDto): Promise<EmailAccount[]> {
+    const accounts = await this.getEmailAccountBySmartleadClientId(
+      smartleadClientId,
+    );
+    const domainCounts = accounts.reduce<Record<string, number>>(
+      (counts, account) => {
+        counts[account.domain] = (counts[account.domain] ?? 0) + 1;
+        return counts;
+      },
+      {},
+    );
+
+    const requiredPool = Math.max(
+      0,
+      Math.floor(
+        totalNumberOfEmailsToSend /
+          numberOfDaysInCampaign /
+          emailsPerInboxPerDay,
+      ),
+    );
+
+    return accounts
+      .sort((left, right) => {
+        const scoreDifference =
+          (right.warmupReputation ?? Number.NEGATIVE_INFINITY) -
+          (left.warmupReputation ?? Number.NEGATIVE_INFINITY);
+        if (scoreDifference) return scoreDifference;
+
+        const campaignDifference =
+          left.numberOfCampaignAssociated - right.numberOfCampaignAssociated;
+        if (campaignDifference) return campaignDifference;
+
+        const domainDifference =
+          (domainCounts[left.domain] ?? 1) -
+          (domainCounts[right.domain] ?? 1);
+        if (domainDifference) return domainDifference;
+
+        return this.creationTime(left) - this.creationTime(right);
+      })
+      .slice(0, requiredPool);
+  }
+
+  async associateEmailAccountsWithCampaign({
+    emailAccountIds,
+    campaignId,
+  }: {
+    emailAccountIds: string[];
+    campaignId: string;
+  }): Promise<EmailAccount[]> {
+    const uniqueIds = [...new Set(emailAccountIds.map(String))];
+    const accounts = await Promise.all(
+      uniqueIds.map((id) => this.findEmailAccount(id)),
+    );
+    const missingIds = uniqueIds.filter((_, index) => !accounts[index]);
+
+    if (missingIds.length) {
+      throw new NotFoundException(
+        `Email account(s) not found: ${missingIds.join(', ')}`,
+      );
+    }
+
+    const updatedAccounts = accounts.map(
+      (account) =>
+        new EmailAccount({
+          ...account,
+          campaignIds: [...account.campaignIds, campaignId],
+        }),
+    );
+    await Promise.all(updatedAccounts.map((account) => this.persist(account)));
+    return updatedAccounts;
+  }
+
+  async saveEmailAccount(
+    emailAccount: EmailAccountDto,
+  ): Promise<EmailAccount> {
+    const remote = await this.getRemoteEmailAccount(
+      String(emailAccount.smartleadInboxId),
+    );
+    const reputation = await this.getRemoteWarmupReputation(
+      String(emailAccount.smartleadInboxId),
+    );
+    const existing = await this.findEmailAccount(
+      String(emailAccount.smartleadInboxId),
+    );
+
+    const account = new EmailAccount({
+      ...existing,
+      ...emailAccount,
+      smartleadInboxId: String(emailAccount.smartleadInboxId),
+      smartleadClientId: String(
+        emailAccount.smartleadClientId ?? remote.client_id,
+      ),
+      email: emailAccount.email ?? remote.from_email ?? remote.email,
+      tags: emailAccount.tags ?? existing?.tags ?? remote.tags ?? [],
+      campaignIds: emailAccount.campaignIds ?? existing?.campaignIds ?? [],
+      createdAt:
+        remote.created_at ?? remote.createdAt ?? emailAccount.createdAt,
+      warmupReputation: reputation,
+    });
+    await this.persist(account);
+    return account;
+  }
+
+  async getEmailAccount(
+    emailAccount: EmailAccountDto | string,
+  ): Promise<EmailAccount> {
+    const id =
+      typeof emailAccount === 'string'
+        ? emailAccount
+        : emailAccount.smartleadInboxId;
+    const account = await this.findEmailAccount(String(id));
+    if (!account) throw new NotFoundException('Email account not found');
+    return account;
+  }
+
+  async getAllEmailAccounts(
+    pagination: { page: number; pageSize: number } = {
+      page: 0,
+      pageSize: 100,
+    },
+  ): Promise<{ emailAccounts: EmailAccount[]; pageCount: number }> {
+    const [response, pageCount] = await Promise.all([
+      this.datastoreService.getByField({
+        documentType: documentType.EMAIL_ACCOUNT,
+        fieldKey: 'data.smartleadInboxId',
+        fieldValue: { $exists: true },
+        pagination,
+      }),
+      this.datastoreService.getPageCount({
+        collection: documentType.EMAIL_ACCOUNT,
+        fieldKey: 'data.smartleadInboxId',
+        fieldValue: { $exists: true },
+      }),
+    ]);
+    return {
+      emailAccounts: this.toAccounts(response?.data),
+      pageCount: pageCount ?? 0,
+    };
+  }
+
+  async getEmailAccountByEmail(email: string): Promise<EmailAccount> {
+    const response = await this.datastoreService.getByField({
+      documentType: documentType.EMAIL_ACCOUNT,
+      fieldKey: 'data.email',
+      fieldValue: email,
+    });
+    const account = this.toAccounts(response?.data)[0];
+    if (!account) throw new NotFoundException('Email account not found');
+    return account;
+  }
+
+  async getEmailAccountBySmartleadClientId(
+    smartleadClientId: string,
+  ): Promise<EmailAccount[]> {
+    const response = await this.datastoreService.getByField({
+      documentType: documentType.EMAIL_ACCOUNT,
+      fieldKey: 'data.smartleadClientId',
+      fieldValue: String(smartleadClientId),
+    });
+    return this.toAccounts(response?.data);
+  }
